$('panel-content').addEventListener('input',e=>{if(e.target.id==='opacity'){$('opacity-value').textContent=e.target.value+'%';document.documentElement.style.setProperty('--card-opacity',Number(e.target.value)/100);}if(e.target.dataset.color){const k=e.target.dataset.color,v=e.target.value;document.querySelector(`[data-color-text="${k}"]`).value=v;}});
