document.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.pointer)return;const d=drag;drag=null;if(d.next)transact(s=>{if(s.settings.theme!==d.theme||stickerTarget!==d.cardKind)throw Error('主题或卡片类型已变化，请重新拖动');const a=s.settings.skins[d.theme].decorations[d.cardKind].find(a=>a.id===d.id);if(a)Object.assign(a,d.next);return s;});else{renderPanel();renderStage();}});
