$('stage').addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('.sticker'))return;const resize=e.target.closest('#stage-resize'),move=e.target.closest('#stage-move');if(!resize&&!move&&e.target.closest('button,input,select,textarea,a'))return;if(drag)return;queueMotion.cancel();const stage=$('stage'),canvas=$('canvas'),start=pendingStagePlacement||doc.settings;stageGesture={kind:resize?'resize':'move',pointer:e.pointerId,startX:e.clientX,startY:e.clientY,width:stage.offsetWidth,height:stage.offsetHeight,canvasWidth:canvas.clientWidth,canvasHeight:canvas.clientHeight,start:{x:start.x,y:start.y,scale:start.scale},preview:{x:start.x,y:start.y,scale:start.scale},moved:false};stage.setPointerCapture(e.pointerId);stage.classList.add('stage-transforming');e.preventDefault();});
