for(const id of ['stage-move','stage-resize'])$(id).addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const positive=e.key==='ArrowRight'||e.key==='ArrowDown',base=pendingStagePlacement||doc.settings;let scale=base.scale,x=base.x,y=base.y;if(id==='stage-resize')scale=Math.max(.5,Math.min(2.5,Math.round((scale+(positive?.05:-.05))*100)/100));else{const step=e.shiftKey?5:1;if(e.key==='ArrowLeft'||e.key==='ArrowRight')x+=positive?step:-step;else y+=positive?step:-step;}commitStagePlacement({...stageBounds(x,y,scale),scale});});
